const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体（示意）' },
      { kind: 'text', payload: '静止释放' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cx = w * 0.5;
    var groundY = h * 0.88;
    var r = Math.max(10, Math.min(w, h) * 0.075);
    var startY = h * 0.16;
    var ballCy = h * 0.45;
    var leftX = cx - r * 2.0;
    var rightX = cx + r * 2.0;
    var arrowTop = ballCy - r * 1.4;
    var arrowBottom = ballCy + r * 1.6;
    var guide = [['M', cx, startY], ['L', cx, groundY - 4]];
    var startTick = [['M', cx - r * 0.9, startY], ['L', cx + r * 0.9, startY]];
    var ground = [['M', w * 0.08, groundY], ['L', w * 0.92, groundY], ['L', w * 0.92, groundY + 3], ['L', w * 0.08, groundY + 3], ['Z']];
    var ball = visualSdk.circle(cx, ballCy, r);
    var shine = visualSdk.circle(cx - r * 0.32, ballCy - r * 0.32, r * 0.22);
    var vArrow = visualSdk.arrow(leftX, arrowTop, leftX, arrowBottom);
    var gArrow = visualSdk.arrow(rightX, arrowTop, rightX, arrowBottom);
    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'guide', commands: guide },
        { id: 'startTick', commands: startTick },
        { id: 'ground', commands: ground },
        { id: 'ball', commands: ball },
        { id: 'shine', commands: shine },
        { id: 'vArrow', commands: vArrow },
        { id: 'gArrow', commands: gArrow }
      ],
      root: { type: 'group', children: [
        { type: 'label', contentId: metrics[0].contentId, anchor: { x: cx, y: h * 0.06 }, hAlign: 'center', vAlign: 'middle', color: '#26354A' },
        { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx, y: startY - 10 }, hAlign: 'center', vAlign: 'bottom', color: '#26354A' },
        { type: 'path', pathId: 'guide', fill: '#9AA9BC', stroke: { width: 2, dash: [6, 6] } },
        { type: 'path', pathId: 'startTick', fill: '#7A8CA6', stroke: { width: 2 } },
        { type: 'path', pathId: 'ground', fill: '#26354A' },
        { type: 'path', pathId: 'ball', fill: '#2F80ED' },
        { type: 'path', pathId: 'shine', fill: '#FFFFFF88' },
        { type: 'path', pathId: 'vArrow', fill: '#1D6FE0' },
        { type: 'path', pathId: 'gArrow', fill: '#C0392B' },
        { type: 'label', contentId: metrics[2].contentId, anchor: { x: leftX - 8, y: (arrowTop + arrowBottom) / 2 }, hAlign: 'right', vAlign: 'middle', color: '#1D6FE0' },
        { type: 'label', contentId: metrics[3].contentId, anchor: { x: rightX + 8, y: (arrowTop + arrowBottom) / 2 }, hAlign: 'left', vAlign: 'middle', color: '#C0392B' }
      ] }
    };
  }
};
